import math
import itertools
from functools import reduce

def task_func(numbers):
    if not numbers:
        return 0.0

    total = 0.0
    for r in range(1, len(numbers) + 1):
        for combo in itertools.combinations(numbers, r):
            product = reduce(lambda acc, x: acc * x, combo, 1)
            total += math.log(product)

    return float(total)
